; ADOFAI SNES: stock 65816 + S-PPU + SPC700, NTSC LoROM.
; All game timing is absolute relative to audio start; a tap never moves the
; song clock. Assets and integer timing tables are generated by Python.
.p816
.smart -
.include "build/constants.inc"

OAM = $0200
HUD = $0800
TAP_MASK = $CFF0
START = $1000
SELECT = $2000

.segment "ZEROPAGE"
tick:           .res 2
last_tick:      .res 2
joy:            .res 2
old_joy:        .res 2
pressed:        .res 2
state:          .res 2       ; 0 title, 1 playing, 2 failed, 3 clear, 4 paused
step:           .res 2       ; landed floor 0..167
elapsed:        .res 2
combo:          .res 2
best:           .res 2
perfects:       .res 2
misses:         .res 2
practice:       .res 2
autoplay:       .res 2
calibration:    .res 2       ; signed frames, positive = later taps
feedback:       .res 2       ; 0 blank, 1 perfect, 2 early, 3 late, 4 miss
feedback_time:  .res 2
timing_error:   .res 2
fail_reason:    .res 2
cam_x:          .res 2
cam_y:          .res 2
angle:          .res 2
orbit_x:        .res 2
orbit_y:        .res 2
sprite_x:       .res 2
sprite_y:       .res 2
sprite_tile:    .res 2
sprite_attr:    .res 2
oam_pos:        .res 2
render_i:       .res 2
render_end:     .res 2
scratch:        .res 2
scratch2:       .res 2
text_ptr:       .res 2
text_attr:      .res 2
number:         .res 2
digit:          .res 2
music_ptr:      .res 3       ; long pointer into LoROM audio banks
packet_seq:     .res 2
packets_left:   .res 2
music_active:   .res 2
hud_state:      .res 2
last_error:     .res 2
audio_ticks:    .res 2
audio_frame:    .res 2
clock_version:  .res 2
clock_fraction: .res 2

.segment "CODE"
.a16
.i16
reset:
    sei
    clc
    xce
    rep #$38
    ldx #$1FFF
    txs
    lda #0
    tcd
    sep #$20
    .a8
    phk
    plb
    lda #$80
    sta $2100
    stz $4200
    stz $420C
    stz $420B
    stz $420D
    ; Initialize low WRAM including the OAM and HUD staging buffers.
    rep #$20
    .a16
    ldx #0
@ram:
    stz $0000,x
    inx
    inx
    cpx #$1E00
    bne @ram
    sep #$20
    .a8
    ldx #$2101
@ppu:
    stz $0000,x
    inx
    cpx #$2134
    bne @ppu
    lda #$80
    sta $2115
    ; VRAM power-up contents are unspecified. Clear it all through DMA.
    stz $2116
    stz $2117
    lda #$09                 ; fixed source, alternate $2118/$2119
    sta $4300
    lda #$18
    sta $4301
    ldx #.loword(zero_word)
    stx $4302
    stz $4304
    stz $4305
    stz $4306               ; length zero = 65536 bytes
    lda #1
    sta $420B
    ; Palette DMA.
    stz $2121
    stz $4300
    lda #$22
    sta $4301
    ldx #.loword(palette)
    stx $4302
    lda #31
    sta $4304
    ldx #512
    stx $4305
    lda #1
    sta $420B
    rep #$20
    .a16
    lda #.loword(background_chr)
    ldx #0
    ldy #background_chr_end-background_chr
    jsr load_vram
    lda #.loword(background_map)
    ldx #$2000
    ldy #2048
    jsr load_vram
    lda #.loword(font_chr)
    ldx #$3000
    ldy #2048
    jsr load_vram
    lda #.loword(object_chr)
    ldx #$4000
    ldy #8192
    jsr load_vram
    sep #$20
    .a8
    lda #$62                 ; 16/32-pixel OBJ sizes; tiles at VRAM $8000
    sta $2101
    lda #$09                 ; Mode 1, BG3 high-priority text
    sta $2105
    lda #$20
    sta $2107
    lda #$28
    sta $2109
    stz $210B
    lda #3
    sta $210C
    stz $210D
    stz $210D
    lda #$FF
    sta $210E
    sta $210E
    stz $2111
    stz $2111
    lda #$FF
    sta $2112
    sta $2112
    lda #$15                 ; BG1 + BG3 + OBJ
    sta $212C
    stz $212D
    rep #$20
    .a16
    lda #$FFFF
    sta hud_state
    jsr spc_upload
    jsr clear_oam
    jsr draw_hud
    jsr render
    sep #$20
    .a8
    lda #$81                 ; VBlank NMI + automatic joypad reads
    sta $4200
    lda #$0F
    sta $2100
    rep #$20
    .a16
main:
    lda tick
    cmp last_tick
    beq main
    sta last_tick
    lda old_joy
    eor #$FFFF
    and joy
    sta pressed
    lda joy
    sta old_joy
    lda state
    beq @title
    cmp #1
    beq @play
    cmp #4
    beq @pause
    cmp #3
    bne @result
    jsr update_tail
@result:
    lda pressed
    bit #SELECT
    bne @quit
    and #TAP_MASK|START
    beq @draw
    jsr start_game
    bra @draw
@title:
    jsr update_title
    bra @draw
@play:
    jsr update_game
    bra @draw
@pause:
    lda pressed
    bit #SELECT
    bne @quit
    bit #START
    beq @draw
    lda #$83
    jsr spc_command
    lda #1
    sta state
    bra @draw
@quit:
    lda #$80
    jsr spc_command
    stz state
    stz music_active
@draw:
    jsr draw_hud
    jsr render
    jmp main

; A16 source, X16 VRAM word address, Y16 byte length, source in bank zero.
load_vram:
    sta $4302
    stx $2116
    sty $4305
    sep #$20
    .a8
    lda #31
    sta $4304
    lda #1
    sta $4300
    lda #$18
    sta $4301
    lda #1
    sta $420B
    rep #$20
    .a16
    rts

; Standard IPL single-block upload to ARAM $0200; execution starts there.
spc_upload:
    sep #$20
    .a8
@ready:
    lda $2140
    cmp #$AA
    bne @ready
    lda $2141
    cmp #$BB
    bne @ready
    ldx #$0200
    stx $2142
    lda #1
    sta $2141
    lda #$CC
    sta $2140
@accept:
    cmp $2140
    bne @accept
    ldy #0
@byte:
    lda spc_image,y
    sta $2141
    tya
    sta $2140
@echo:
    cmp $2140
    bne @echo
    iny
    cpy #spc_image_end-spc_image
    bne @byte
    ; Any counter different from the next data byte signals a new block.
    ldx #$0200
    stx $2142
    stz $2141
    tya
    inc a
    sta $2140
@boot:
    lda $2140
    bne @boot
    rep #$20
    .a16
    rts

; A = command ID. Interrupts may run while a handshake is in flight.
spc_command:
    sep #$20
    .a8
    sta $2140
@ack:
    cmp $2140
    bne @ack
    rep #$20
    .a16
    rts

; Transfer packets_left groups of three bytes to the SPC circular buffer.
stream_packets:
    lda packets_left
    beq @done
    sep #$20
    .a8
@packet:
    ldy #0
    lda [music_ptr],y
    sta $2141
    iny
    lda [music_ptr],y
    sta $2142
    iny
    lda [music_ptr],y
    sta $2143
    lda packet_seq
    inc a
    and #$7F
    sta packet_seq
    sta $2140
@ack:
    cmp $2140
    bne @ack
    rep #$20
    .a16
    lda music_ptr
    clc
    adc #3
    cmp #$FFF8
    bne @nowrap
    lda #$8000
    sep #$20
    .a8
    inc music_ptr+2
    rep #$20
    .a16
@nowrap:
    sta music_ptr
    dec packets_left
    beq @done
    sep #$20
    .a8
    bra @packet
@done:
    rep #$20
    .a16
    rts

start_game:
    lda #$80
    jsr spc_command
    lda #.loword(text_loading)
    ldy #22*64+8*2
    jsr put_text
    stz step
    stz elapsed
    stz audio_frame
    stz combo
    stz perfects
    stz misses
    stz feedback
    stz feedback_time
    stz timing_error
    stz packet_seq
    lda #$8000
    sta music_ptr
    sep #$20
    .a8
    lda #1
    sta music_ptr+2
    rep #$20
    .a16
    lda #5460                ; preload half the ring (~1.82 s of audio)
    sta packets_left
    jsr stream_packets
    lda #$FFA0               ; camera centers floor zero at (96,116)
    sta cam_x
    lda #140
    sta cam_y
    lda #1
    sta state
    jsr draw_hud
    jsr render
    lda tick
@sync:
    cmp tick
    beq @sync
    lda tick
    sta last_tick
    lda #$81
    jsr spc_command
    lda #1
    sta music_active
    sta state
    rts

update_title:
    lda pressed
    bit #$0200               ; LEFT: one frame earlier
    beq @right
    lda calibration
    cmp #$FFF8
    beq @right
    dec calibration
@right:
    lda pressed
    bit #$0100
    beq @modes
    lda calibration
    cmp #8
    beq @modes
    inc calibration
@modes:
    lda pressed
    bit #$4000               ; Y: deterministic showcase
    beq @practice
    stz practice
    lda #1
    sta autoplay
    jmp start_game
@practice:
    bit #$0040               ; X: misses continue instead of ending attempt
    beq @normal
    stz autoplay
    lda #1
    sta practice
    jmp start_game
@normal:
    bit #$1080               ; A or START
    beq @done
    stz autoplay
    stz practice
    jmp start_game
@done:
    rts

update_game:
    lda pressed
    bit #SELECT
    beq @pause
    jmp start_game
@pause:
    bit #START
    beq @run
    lda #$82
    jsr spc_command
    lda #4
    sta state
    rts
@run:
    jsr read_audio_clock
    jsr stream_frame
    lda feedback_time
    beq @timing
    dec feedback_time
@timing:
    lda step
    inc a
    asl a
    tax
    lda elapsed
    sec
    sbc note_time,x
    sec
    sbc calibration
    sta timing_error
    lda autoplay
    beq @human
    lda timing_error
    bmi @done
    stz timing_error
    jmp hit
@human:
    lda pressed
    and #TAP_MASK
    beq @late
    lda step
    bne @judge
    lda elapsed
    cmp #FIRST_HIT-8
    bcc @done                ; ignore taps during the four-beat count-in
@judge:
    lda timing_error
    bpl @positive
    eor #$FFFF
    inc a
@positive:
    cmp #5                   ; +/-4 frames, independent of orbital speed
    bcs @bad_tap
    jmp hit
@bad_tap:
    lda timing_error
    bmi @early_fail
    bra @late_fail
@early_fail:
    stz fail_reason
    lda practice
    bne @done                ; an early practice tap doesn't consume a tile
    jmp fail
@late:
    lda timing_error
    bmi @done
    cmp #5
    bcc @done
@late_fail:
    lda #1
    sta fail_reason
    lda practice
    beq @fail
    inc misses
    stz combo
    lda timing_error
    sta last_error
    lda #4
    sta feedback
    lda #24
    sta feedback_time
    jmp advance
@fail:
    jmp fail
@done:
    rts

hit:
    lda timing_error
    sta last_error
    inc combo
    lda autoplay
    bne @grade
    lda combo
    cmp best
    bcc @grade
    sta best
@grade:
    lda timing_error
    bpl @abs
    eor #$FFFF
    inc a
@abs:
    cmp #2
    bcs @off
    inc perfects
    lda #1
    bra @feedback
@off:
    lda #2
    ldx timing_error
    bmi @feedback
    inc a
@feedback:
    sta feedback
    lda #20
    sta feedback_time
advance:
    inc step
    lda step
    cmp #167
    bcc @done
    lda #3
    sta state
@done:
    rts
fail:
    inc misses
    lda #2
    sta state
    lda #$82
    jsr spc_command
    stz music_active
    rts

update_tail:
    lda music_active
    beq @done
    jsr read_audio_clock
    lda elapsed
    cmp #STREAM_END-1
    bcc stream_frame
    lda #$82
    jsr spc_command
    stz music_active
@done:
    rts
stream_frame:
    stz packets_left
    lda audio_frame
@catchup:
    cmp elapsed
    bcs @transfer
    inc a
    sta audio_frame
    tax
    sep #$20
    .a8
    lda stream_counts,x
    rep #$20
    .a16
    and #$FF
    clc
    adc packets_left
    sta packets_left
    lda audio_frame
    bra @catchup
@transfer:
    jmp stream_packets

; Musical time comes from the SPC timer, so the orbit and judgments follow
; the actual audio crystal, including emulators/hardware with different APU
; rates. Convert 4 ms timer ticks to a 60.0988 Hz virtual frame count using
; four 256-entry partial-product tables (rounded 16.16 multiplication).
read_audio_clock:
    sep #$20
    .a8
@snapshot:
    lda $2143
    bit #1
    bne @snapshot
    sta clock_version
    rep #$20
    .a16
    lda $2141
    sta audio_ticks
    sep #$20
    .a8
    lda $2143
    cmp clock_version
    bne @snapshot
    rep #$20
    .a16
    lda audio_ticks
    and #$FF
    asl a
    tax
    lda clock_lo_low,x
    sta clock_fraction
    lda clock_lo_high,x
    sta scratch
    lda audio_ticks
    xba
    and #$FF
    asl a
    tax
    lda clock_hi_low,x
    clc
    adc clock_fraction
    sta clock_fraction
    lda clock_hi_high,x
    adc scratch
    sta scratch
    lda clock_fraction
    clc
    adc #$8000
    lda scratch
    adc #0
    sta elapsed
    rts

; HUD templates live in ROM; numbers/feedback are written into the WRAM map.
draw_hud:
    lda state
    cmp hud_state
    beq @dynamic
    sta hud_state
    asl a
    tax
    lda hud_templates,x
    sta text_ptr
    ldy #0
@copy:
    lda (text_ptr),y
    sta HUD,y
    iny
    iny
    cpy #2048
    bne @copy
@dynamic:
    lda state
    bne @game
    ldy #26*64+21*2           ; replace offset sign and magnitude in title
    lda calibration
    bpl @plus
    eor #$FFFF
    inc a
    pha
    lda #'-'|($30<<8)
    sta HUD,y
    pla
    bra @offset
@plus:
    pha
    lda #'+'|($30<<8)
    sta HUD,y
    pla
@offset:
    clc
    adc #'0'
    ora #$3000
    sta HUD+2,y
    rts
@game:
    lda combo
    ldy #3*64+8*2
    jsr put3
    lda best
    ldy #3*64+19*2
    jsr put3
    ldx step
    lda note_progress,x
    and #$FF
    ldy #3*64+26*2
    jsr put3
    lda state
    cmp #3
    bne @failed
    lda perfects
    ldy #13*64+11*2
    jsr put3
    lda misses
    ldy #13*64+25*2
    jsr put3
    lda autoplay
    beq @practice_result
    lda #.loword(text_demo_clear)
    ldy #10*64+8*2
    jsr put_text
@practice_result:
    lda practice
    beq @done
    lda #.loword(text_practice)
    ldy #20*64+12*2
    jsr put_text
@done:
    rts
@failed:
    cmp #2
    bne @playing
    lda fail_reason
    bne @late
    lda #.loword(text_too_early)
    bra @reason
@late:
    lda #.loword(text_too_late)
@reason:
    ldy #12*64+8*2
    jsr put_text
    rts
@playing:
    cmp #4
    beq @done
    ; Erase the small transient areas without copying a full 2 KiB map.
    ldx #0
    lda #0
@erase:
    sta HUD+8*64+10*2,x
    sta HUD+10*64+10*2,x
    sta HUD+21*64+10*2,x
    inx
    inx
    cpx #24
    bne @erase
    lda autoplay
    beq @practice
    lda #.loword(text_auto)
    bra @mode
@practice:
    lda practice
    beq @count
    lda #.loword(text_practice)
@mode:
    ldy #5*64+12*2
    jsr put_text
@count:
    lda step
    bne @feedback
    lda elapsed
    cmp #FIRST_HIT
    bcs @feedback
    lda #.loword(text_ready)
    ldy #8*64+12*2
    jsr put_text
    lda #4
    ldx elapsed
    cpx #FIRST_HIT-72
    bcc @count_number
    dec a
    cpx #FIRST_HIT-48
    bcc @count_number
    dec a
    cpx #FIRST_HIT-24
    bcc @count_number
    dec a
@count_number:
    clc
    adc #'0'
    ora #$3C00
    sta HUD+10*64+15*2
    rts
@feedback:
    lda feedback_time
    beq @meter
    lda feedback
    asl a
    tax
    lda feedback_text,x
    ldy #21*64+12*2
    jsr put_text
@meter:
    ; Nine-character timing indicator, with a center mark and last tap.
    lda #.loword(text_meter)
    ldy #22*64+11*2
    jsr put_text
    lda feedback_time
    bne @has_mark
    rts
@has_mark:
    lda last_error
    cmp #$FFFC
    bcs @mark
    cmp #5
    bcc @mark
    rts
@mark:
    clc
    adc #4
    asl a
    clc
    adc #22*64+11*2
    tay
    lda #'+'|$3800
    sta HUD,y
    rts

; Draw NUL-terminated ASCII at byte offset Y in the HUD map.
put_text:
    sta text_ptr
    sep #$20
    .a8
@char:
    lda (text_ptr)
    beq @done
    sta HUD,y
    lda #$3C
    sta HUD+1,y
    inc text_ptr
    bne @next
    inc text_ptr+1
@next:
    iny
    iny
    bra @char
@done:
    rep #$20
    .a16
    rts
put3:
    sta number
    lda #0
    sta digit
@hundreds:
    lda number
    cmp #100
    bcc @h
    sec
    sbc #100
    sta number
    inc digit
    bra @hundreds
@h:
    lda digit
    jsr put_digit
    stz digit
@tens:
    lda number
    cmp #10
    bcc @t
    sec
    sbc #10
    sta number
    inc digit
    bra @tens
@t:
    lda digit
    jsr put_digit
    lda number
put_digit:
    clc
    adc #'0'
    sep #$20
    .a8
    sta HUD,y
    rep #$20
    .a16
    iny
    iny
    rts

clear_oam:
    ldx #0
    lda #$E000
@hide:
    sta OAM,x
    stz OAM+2,x
    inx
    inx
    inx
    inx
    cpx #512
    bne @hide
    ldx #0
@high:
    stz OAM+512,x
    inx
    inx
    cpx #32
    bne @high
    stz oam_pos
    rts

; Append a 16x16 sprite, with signed clipping and the 9th OAM X bit.
sprite:
    lda sprite_x
    cmp #$FFF1
    bcs @xok
    cmp #256
    bcs @done
@xok:
    lda sprite_y
    cmp #32
    bcc @done
    cmp #177
    bcs @done
    ldx oam_pos
    sep #$20
    .a8
    lda sprite_x
    sta OAM,x
    lda sprite_y
    sta OAM+1,x
    lda sprite_tile
    sta OAM+2,x
    lda sprite_attr
    sta OAM+3,x
    rep #$20
    .a16
    lda sprite_x
    bpl @added
    txa
    and #12
    lsr a
    tay
    lda xhigh_masks,y
    sta scratch2
    txa
    lsr a
    lsr a
    lsr a
    lsr a
    tax
    sep #$20
    .a8
    lda OAM+512,x
    ora scratch2
    sta OAM+512,x
    rep #$20
    .a16
@added:
    lda oam_pos
    clc
    adc #4
    sta oam_pos
@done:
    rts

render:
    jsr clear_oam
    lda state
    cmp #1
    beq @level
    lda #112
    ldx state
    beq @emblem
    lda #152
@emblem:
    sta render_end
    lda tick
    asl a
    and #255
    sta angle
    jsr sine_cosine
    lda orbit_x
    clc
    adc #120
    sta sprite_x
    lda orbit_y
    jsr quarter_signed
    sta orbit_y
    clc
    adc render_end
    sta sprite_y
    lda #6
    sta sprite_tile
    lda #$32
    sta sprite_attr
    jsr sprite
    lda #120
    sec
    sbc orbit_x
    sta sprite_x
    lda render_end
    sec
    sbc orbit_y
    sta sprite_y
    lda #$34
    sta sprite_attr
    jmp sprite
@level:
    lda step
    asl a
    tax
    ; Ease the camera by one quarter of the remaining signed distance.
    lda note_x,x
    sec
    sbc #96
    sec
    sbc cam_x
    jsr quarter_signed
    clc
    adc cam_x
    sta cam_x
    lda note_y,x
    sec
    sbc #116
    sec
    sbc cam_y
    jsr quarter_signed
    clc
    adc cam_y
    sta cam_y
    ; Orbit position comes from the scheduled arrival, not the last tap.
    lda step
    bne @normal_angle
    lda elapsed
    cmp #FIRST_HIT
    bcs @normal_angle
    tax
    lda countdown_angle,x
    and #255
    sta angle
    bra @planets
@normal_angle:
    lda step
    asl a
    tax
    lda elapsed
    sec
    sbc note_time,x
    bpl @delta
    lda #0
@delta:
    and #255
    tay
    ldx step
    lda note_slow,x
    and #255
    beq @fast
    lda phase_slow,y
    bra @phase
@fast:
    lda phase_fast,y
@phase:
    and #255
    clc
    adc note_angle,x
    and #255
    sta angle
@planets:
    jsr sine_cosine
    ; Draw planets before the track so they win OBJ overlap priority.
    lda step
    and #1
    asl a
    clc
    adc #$32
    sta sprite_attr
    lda #6
    sta sprite_tile
    jsr pivot_position
    jsr sprite
    lda sprite_attr
    eor #6                   ; alternate fire/ice pivot roles
    sta sprite_attr
    jsr pivot_position
    lda sprite_x
    clc
    adc orbit_x
    sta sprite_x
    lda sprite_y
    clc
    adc orbit_y
    sta sprite_y
    jsr sprite
    ; A small afterimage makes the rotation direction readable.
    lda angle
    sec
    sbc #14
    and #255
    sta angle
    jsr sine_cosine
    jsr pivot_position
    lda sprite_x
    clc
    adc orbit_x
    sta sprite_x
    lda sprite_y
    clc
    adc orbit_y
    sta sprite_y
    lda #10
    sta sprite_tile
    jsr sprite
    ; Next landing marker.
    lda step
    cmp #167
    bcs @track
    inc a
    sta render_i
    jsr tile_position
    lda #8
    sta sprite_tile
    lda #$34
    sta sprite_attr
    jsr sprite
@track:
    lda step
    sec
    sbc #6
    bpl @begin
    lda #0
@begin:
    sta render_i
    lda step
    clc
    adc #14
    cmp #168
    bcc @end
    lda #168
@end:
    sta render_end
@tile:
    jsr tile_position
    lda #$20
    sta sprite_attr
    stz sprite_tile
    lda render_i
    cmp step
    bcc @past
    beq @current
    bra @portal
@past:
    lda #2
    sta sprite_tile
    bra @portal
@current:
    lda #4
    sta sprite_tile
@portal:
    lda render_i
    cmp #167
    bne @draw
    lda #12
    sta sprite_tile
    lda #$26
    sta sprite_attr
@draw:
    jsr sprite
    inc render_i
    lda render_i
    cmp render_end
    bcc @tile
    rts

quarter_signed:
    cmp #$8000
    ror a
    cmp #$8000
    ror a
    ; Round negative values toward zero to avoid camera bias.
    bpl @done
    inc a
@done:
    rts
pivot_position:
    lda step
    sta render_i
tile_position:
    lda render_i
    asl a
    tax
    lda note_x,x
    sec
    sbc cam_x
    sec
    sbc #8
    sta sprite_x
    lda note_y,x
    sec
    sbc cam_y
    sec
    sbc #8
    sta sprite_y
    rts
sine_cosine:
    ldx angle
    lda cos24,x
    and #255
    cmp #128
    bcc @cx
    ora #$FF00
@cx:
    sta orbit_x
    lda sin24,x
    and #255
    cmp #128
    bcc @sy
    ora #$FF00
@sy:
    sta orbit_y
    rts

; NMI commits the completed frame, then samples the automatically read pad.
nmi:
    php
    rep #$30
    .a16
    .i16
    pha
    phx
    phy
    phb
    phk
    plb
    sep #$20
    .a8
    lda $4210
    stz $2102
    stz $2103
    stz $4300
    lda #4
    sta $4301
    ldx #OAM
    stx $4302
    stz $4304
    ldx #544
    stx $4305
    lda #1
    sta $420B
    ldx #$2800
    stx $2116
    lda #1
    sta $4300
    lda #$18
    sta $4301
    ldx #HUD
    stx $4302
    stz $4304
    ldx #2048
    stx $4305
    lda #1
    sta $420B
@pad:
    lda $4212
    and #1
    bne @pad
    rep #$20
    .a16
    lda $4218
    sta joy
    inc tick
    plb
    ply
    plx
    pla
    plp
    rti
irq:
    rti

